"use client";

import * as React from "react";
import { useChoreography } from "@/lib/cojeev-motion/choreography";
import { useDisclosureHeight } from "@/lib/cojeev-motion/use-disclosure-height";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Icon } from "@/components/ui/icon";
import * as Primitive from "@radix-ui/react-collapsible";
export const collapsibleVariants = cva("v-collapsible");
export type CollapsibleAppearance = "inline" | "checklist" | "inspector";
export type CollapsibleProps = React.ComponentProps<typeof Primitive.Root> & {
  appearance?: CollapsibleAppearance;
};
export function Collapsible({
  className,
  appearance,
  ...props
}: CollapsibleProps) {
  const { quiet } = useChoreography();
  return (
    <Primitive.Root
      data-slot="collapsible"
      data-part="root"
      data-appearance={appearance}
      data-motion-quiet={quiet || undefined}
      className={cn(collapsibleVariants(), className)}
      {...props}
    />
  );
}
export type CollapsibleTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
> & { indicator?: React.ReactNode };
export function CollapsibleTrigger({
  className,
  children,
  indicator,
  ...props
}: CollapsibleTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="collapsible-trigger"
      data-part="trigger"
      className={cn(
        "inline-flex items-center gap-2 min-h-11 text-[length:var(--fs-control)] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    >
      {props.asChild ? (
        children
      ) : (
        <>
          {children}
          {indicator ?? <CollapsibleIndicator />}
        </>
      )}
    </Primitive.Trigger>
  );
}
export type CollapsibleContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function CollapsibleContent({
  className,
  ref,
  children,
  ...props
}: CollapsibleContentProps) {
  const contentRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => contentRef.current!);
  useDisclosureHeight(contentRef, props.style?.animationName);
  return (
    <Primitive.Content
      ref={contentRef}
      data-slot="collapsible-content"
      data-part="content"
      className={cn("v-collapsible__body text-[13px]", className)}
      {...props}
    >
      <div data-disclosure-inner>{children}</div>
    </Primitive.Content>
  );
}
export type CollapsibleIndicatorProps = React.ComponentProps<"svg">;
export function CollapsibleIndicator({
  className,
  ...props
}: CollapsibleIndicatorProps) {
  return (
    <Icon
      name="chevron-down"
      data-slot="collapsible-indicator"
      data-part="indicator"
      aria-hidden="true"
      viewBox="0 0 24 24"
      className={cn("v-icon v-chev", className)}
      {...props}
    />
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-collapsible:where([data-slot="collapsible"], [data-slot^="collapsible-"])
  [data-slot="collapsible-trigger"] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  list-style: none;
  cursor: pointer;
  font-size: var(--fs-control);
  color: var(--muted-foreground);
  min-height: 44px;
  height: auto;
}
.v-collapsible:where([data-slot="collapsible"], [data-slot^="collapsible-"])
  [data-slot="collapsible-trigger"]::-webkit-details-marker {
  display: none;
}
.v-collapsible:where(
    [data-slot="collapsible"],
    [data-slot^="collapsible-"]
  )[data-state="open"]
  [data-slot="collapsible-trigger"]
  .v-chev {
  transform: rotate(180deg);
}
.v-collapsible__body:where(
  [data-slot="collapsible"],
  [data-slot^="collapsible-"]
) {
  margin: 0;
  padding: 0;
  overflow: hidden;
  font-size: 13px;
}
.v-collapsible__body > [data-disclosure-inner] {
  padding: var(--s-3) var(--s-4);
  background: var(--card);
  border-radius: var(--r-md);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="collapsible"],
  [data-slot^="collapsible-"],
  [data-slot="collapsible"]::before,
  [data-slot="collapsible"]::after,
  [data-slot^="collapsible-"]::before,
  [data-slot^="collapsible-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="collapsible-content"][data-state="open"] {
  animation: none;
}
[data-slot="collapsible-content"][data-state="closed"] {
  pointer-events: none;
}
[data-slot="collapsible-trigger"]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.v-collapsible
  [data-slot="collapsible-content"][data-state="closed"]:not([hidden]) {
  display: block;
  animation: v-collapsible-retain var(--disclosure-exit-duration, 220ms) linear;
}
@keyframes v-collapsible-retain {
  from {
    visibility: visible;
  }
  to {
    visibility: visible;
  }
}
.v-collapsible [data-slot="collapsible-indicator"] {
  width: 20px;
  height: 20px;
  flex: none;
  transition: transform var(--t-element) var(--enter);
}
.v-collapsible[data-appearance] {
  width: 100%;
  max-width: 640px;
  min-width: 0;
  color: var(--v-text);
}
.v-collapsible[data-appearance] [data-slot="collapsible-trigger"] {
  width: 100%;
  justify-content: space-between;
  gap: 20px;
  min-height: 52px;
  padding: 12px 0;
  color: inherit;
  text-align: start;
  font-weight: 500;
  border-radius: 0;
}
.v-collapsible[data-appearance] [data-disclosure-inner] {
  background: transparent;
  padding: 4px 0 20px;
  border-radius: 0;
}
.v-collapsible[data-appearance] [data-disclosure-inner] p {
  margin: 0 0 12px;
  font-size: 14px;
  line-height: 1.7;
  color: var(--v-text-2);
  max-width: 60ch;
}
.v-collapsible[data-appearance="inline"] {
  border-block: 1px solid var(--v-border);
}
.v-collapsible__summary {
  display: grid;
  gap: 5px;
}
.v-collapsible__summary small {
  color: var(--v-text-2);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.4;
}
.v-collapsible[data-appearance="checklist"] {
  border-radius: 20px;
  border: 1px solid var(--v-border);
  background: var(--card);
  padding: 10px 22px;
}
.v-collapsible__checklist {
  list-style: none;
  margin: 0 0 16px;
  padding: 0;
  display: grid;
  gap: 4px;
}
.v-collapsible__checklist li {
  display: flex;
  gap: 14px;
  align-items: center;
  min-height: 52px;
  font-size: 14px;
  line-height: 1.5;
}
.v-collapsible__checklist li > span {
  display: grid;
  place-items: center;
  flex: none;
  width: 32px;
  height: 32px;
  border-radius: 50% 50% 42% 58%;
  background: var(--v-olive);
  color: var(--v-on-accent);
  font-size: 11px;
}
.v-collapsible[data-appearance="inspector"] {
  border-radius: 20px;
  border: 1px solid var(--v-border);
  overflow: hidden;
  background: var(--card);
}
.v-collapsible[data-appearance="inspector"] [data-slot="collapsible-trigger"] {
  padding: 20px;
  background: color-mix(in srgb, var(--v-blue) 13%, var(--card));
}
.v-collapsible[data-appearance="inspector"] [data-disclosure-inner] {
  padding: 0 20px 12px;
}
.v-collapsible__inspector {
  margin: 0 0 12px;
}
.v-collapsible__inspector > div {
  display: grid;
  grid-template-columns: minmax(85px, 0.8fr) minmax(0, 1.2fr);
  gap: 20px;
  padding: 14px 0;
  border-bottom: 1px solid var(--v-border);
  font-size: 13px;
  line-height: 1.5;
}
.v-collapsible__inspector dt {
  color: var(--v-text-2);
}
.v-collapsible__inspector dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.v-collapsible__link {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  gap: 8px;
  color: var(--v-text);
  font-size: 13px;
  text-underline-offset: 4px;
}
.v-collapsible[data-motion-quiet="true"] [data-slot="collapsible-indicator"] {
  transition: none;
}
@media (prefers-reduced-motion: reduce) {
  .v-collapsible [data-slot="collapsible-content"][data-state="closed"] {
    animation-duration: 0s;
  }
}

}
